#!/usr/bin/env bash
# Source after cd to the repo root. .lab.env is generated by the bootstrap stage.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
if [ -f .lab.env ]; then
  # Only a validated IP and CIDR are written here by the bootstrap stage.
  set -a; source .lab.env; set +a
fi
export LAB_IP="${LAB_IP:-10.3.10.137}"
export CLIENT_NET="${CLIENT_NET:-}"
NAMES='vibeshop.test attacker.test legacy.vibeshop.test evil.test'
sudo_if_needed() { if [ "$(id -u)" = 0 ]; then "$@"; else sudo "$@"; fi; }
compose() {
  local args=()
  [ ! -f "$ROOT/.lab.env" ] || args=(--env-file "$ROOT/.lab.env")
  if docker info >/dev/null 2>&1; then docker compose "${args[@]}" "$@";
  else sudo docker compose "${args[@]}" "$@"; fi
}
